/* selectMasterMdCmCatlgRcmdList */ SELECT DOC_NAME, TARGET, KEY_1 AS DESCRIPTION, KEY_2 AS SPECIFICATION, KEY_3 AS MAKER_NAME, KEY_4 AS MODEL_PART_NO, KEY_5 AS REMARK, KEY_6 AS CMS_CATLG_ID, KEY_7 AS CMS_MAKER_CODE, KEY_8 AS CMS_MAKER_NAME, KEY_9 AS CMS_ORIGIN_CODE, KEY_10 AS CMS_ORIGIN_NAME, KEY_11 AS UNIT_MEASRUE, KEY_12 AS ITEM_GUBUN, KEY_13 AS SG_ID, KEY_14 AS SG_NAME, KEY_15 AS ACCR_RATE, KEY_21 AS IMG, KEY_22 AS CMS_DESCRIPTION, KEY_23 AS CMS_SPECIFICATION FROM BNTTRXL WHERE 1=1 AND DOC_NAME = 'CATLG_RCMD' AND KEY_20 = #{st_user_id}
AND KEY_15 >= #{st_target_rate}
ORDER BY TO_NUMBER(TARGET)

